insert into public.orgcue_tables (name, domain, scope, title, description, columns, sort) values
  ('assignment_requests', 'collaboration', 'workspace', 'Assignment requests', 'A request to accept a task, an action, a hand-over or the ownership of a record. Status: open, accepted, declined, proposed (a new date waits for the asker) or withdrawn. The committed date is kept apart from the record''s due date.', '[{"name":"ref","type":"text","ref":null,"enforced":false},{"name":"kind","type":"text","ref":null,"enforced":false},{"name":"from_id","type":"text","ref":"people","enforced":false},{"name":"to_id","type":"text","ref":"people","enforced":false},{"name":"asked_on","type":"date","ref":null,"enforced":false},{"name":"target_date","type":"date","ref":null,"enforced":false},{"name":"note","type":"text","ref":null,"enforced":false},{"name":"status","type":"text","ref":null,"enforced":false},{"name":"answered_on","type":"date","ref":null,"enforced":false},{"name":"reason","type":"text","ref":null,"enforced":false},{"name":"proposed_date","type":"date","ref":null,"enforced":false},{"name":"committed_date","type":"date","ref":null,"enforced":false},{"name":"decided_on","type":"date","ref":null,"enforced":false},{"name":"nudged_on","type":"date","ref":null,"enforced":false}]'::jsonb, 0),
  ('comment_reactions', 'collaboration', 'workspace', 'Comment reactions', 'A person''s reaction to a comment (up, yes, eyes or tada).', '[{"name":"comment_id","type":"text","ref":"comments","enforced":true},{"name":"person_id","type":"text","ref":"people","enforced":false},{"name":"reaction","type":"text","ref":null,"enforced":false}]'::jsonb, 1),
